src/gameplay/weaver/WeaverBrainSystem.ts:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { WeaverAIComponent, HealthComponent } from "../../core/ecs/Components";
import { GameEvent } from "../../core/events/GameEvents";
import { IWeaverState, WeaverStateType } from "./IWeaverState";
import { WEAVER_AI_TUNING } from "../../core/engine/ArenaConfig";
import { SystemContext } from "../../core/engine/SystemContext";
import { WeaverSweepingState } from "./states/WeaverSweepingState";
import { WeaverDashingState } from "./states/WeaverDashingState";
import { WeaverReturningState } from "./states/WeaverReturningState";
import { WeaverDefeatedState } from "./states/WeaverDefeatedState";

export class WeaverBrainSystem implements ISystem {
  readonly phase = SystemPhase.Intents;
  private states = new Map<WeaverStateType, IWeaverState>();
  private activeState: IWeaverState | null = null;
  private unsubDamage: (() => void) | null = null;
  private unsubReset: (() => void) | null = null;
  private pendingTransition: WeaverStateType | null = null;

  constructor(private context: SystemContext) {
    this.states.set("SWEEPING", new WeaverSweepingState());
    this.states.set("DASHING", new WeaverDashingState());
    this.states.set("RETURNING", new WeaverReturningState());
    this.states.set("DEFEATED", new WeaverDefeatedState());
  }

  public init(): void {
    this.resetBrain();

    this.unsubReset = this.context.broker.subscribe(GameEvent.GAME_RESET, () => {
      this.resetBrain();
    });

    this.unsubDamage = this.context.broker.subscribe(GameEvent.WEAVER_DAMAGED, () => {
      const aiComp = this.context.stores
        .get<WeaverAIComponent>("weaverAI")
        .get(this.context.refs.weaver);
      const health = this.context.stores
        .get<HealthComponent>("health")
        .get(this.context.refs.weaver);

      if (aiComp && health) {
        aiComp.damageShearIntensity = 1.0;
        aiComp.damageShearTime = 0.0;
        if (health.current <= 0) {
          this.pendingTransition = "DEFEATED";
        } else if (aiComp.state === "SWEEPING") {
          this.pendingTransition = "DASHING";
        }
      }
    });
  }

  private resetBrain(): void {
    const aiComp = this.context.stores
      .get<WeaverAIComponent>("weaverAI")
      .get(this.context.refs.weaver);
    if (aiComp) {
      const startState = "SWEEPING" as WeaverStateType;
      const stateObj = this.states.get(startState) || this.states.get("SWEEPING")!;

      aiComp.state = stateObj.type;
      aiComp.hue = stateObj.hue;
      aiComp.timeInState = 0;

      this.activeState = stateObj;
      this.activeState.enter(this.context);
      this.publishStateChangeEvent(stateObj.name, stateObj.hue);
    }
    this.pendingTransition = null;
  }

  private publishStateChangeEvent(name: string, hue: string): void {
    const health = this.context.stores.get<HealthComponent>("health").get(this.context.refs.weaver);
    const isBerserk = health
      ? health.current < health.max * WEAVER_AI_TUNING.BERSERK_HP_THRESHOLD
      : false;
    let finalName = name;

    if (isBerserk && this.activeState?.type !== "DEFEATED") {
      finalName = `${name} (BERSERK)`;
    }
    this.context.broker.publish(GameEvent.WEAVER_STATE_CHANGE, {
      state: finalName,
      hue: hue
    });
  }

  private transitionTo(nextStateKey: WeaverStateType): void {
    const aiComp = this.context.stores
      .get<WeaverAIComponent>("weaverAI")
      .get(this.context.refs.weaver);
    if (!aiComp || !this.activeState) return;

    const nextStateObj = this.states.get(nextStateKey);
    if (nextStateObj && nextStateKey !== this.activeState.type) {
      this.activeState.exit(this.context);

      aiComp.state = nextStateObj.type;
      aiComp.hue = nextStateObj.hue;
      aiComp.timeInState = 0;

      this.activeState = nextStateObj;
      this.activeState.enter(this.context);

      this.publishStateChangeEvent(nextStateObj.name, nextStateObj.hue);
    }
  }

  public update(dt: number): void {
    const aiComp = this.context.stores
      .get<WeaverAIComponent>("weaverAI")
      .get(this.context.refs.weaver);
    if (!aiComp || !this.activeState) return;

    if (this.pendingTransition !== null) {
      this.transitionTo(this.pendingTransition);
      this.pendingTransition = null;
    }

    const pHealth = this.context.stores
      .get<HealthComponent>("health")
      .get(this.context.refs.player);
    if (pHealth && pHealth.current <= 0) {
      this.context.commands.dispatch({
        type: "SET_KINEMATIC_VELOCITY",
        entityId: this.context.refs.weaver,
        x: 0,
        y: 0,
        z: 0
      });
      return;
    }

    const nextStateKey = this.activeState.update(this.context, dt);

    if (nextStateKey && nextStateKey !== this.activeState.type) {
      this.transitionTo(nextStateKey);
    }
  }

  public dispose(): void {
    if (this.unsubDamage) this.unsubDamage();
    if (this.unsubReset) this.unsubReset();
  }
}

src/gameplay/weaver/WeaverTraversalSyste:
import { ISystem } from "../../contracts/ISystem";
import { SystemPhase } from "../../contracts/SystemPhase";
import { SystemContext } from "../../core/engine/SystemContext";
import {
  KinematicVelocityComponent,
  WeaverTraversalComponent,
  TransformComponent,
  KinematicTargetComponent,
  WeaverAIComponent,
  HealthComponent
} from "../../core/ecs/Components";
import { ARENA_CONFIG, WEAVER_AI_TUNING } from "../../core/engine/ArenaConfig";
import * as BABYLON from "@babylonjs/core";

export class WeaverTraversalSystem implements ISystem {
  readonly phase = SystemPhase.Kinematics;
  private minX = ARENA_CONFIG.HORIZONTAL.WEAVER_PATROL_MIN_X;
  private maxX = ARENA_CONFIG.HORIZONTAL.WEAVER_PATROL_MAX_X;

  constructor(private context: SystemContext) {}

  public update(dt: number): void {
    const vel = this.context.stores
      .get<KinematicVelocityComponent>("velocity")
      .get(this.context.refs.weaver);
    const trav = this.context.stores
      .get<WeaverTraversalComponent>("weaverTraversal")
      .get(this.context.refs.weaver);
    const trans = this.context.stores
      .get<TransformComponent>("transform")
      .get(this.context.refs.weaver);
    const target = this.context.stores
      .get<KinematicTargetComponent>("target")
      .get(this.context.refs.weaver);
    const ai = this.context.stores.get<WeaverAIComponent>("weaverAI").get(this.context.refs.weaver);
    const health = this.context.stores.get<HealthComponent>("health").get(this.context.refs.weaver);

    if (!vel || !trav || !trans || !target) return;

    const isSweeping = !ai || ai.state === "SWEEPING";
    if (isSweeping) {
      let nextX = trans.x + vel.x * dt;
      const isBerserk = health
        ? health.current < health.max * WEAVER_AI_TUNING.BERSERK_HP_THRESHOLD
        : false;
      const sweepSpeed = isBerserk
        ? WEAVER_AI_TUNING.PATROL.SPEED_BERSERK
        : WEAVER_AI_TUNING.PATROL.SPEED_NORMAL;
      if (nextX >= this.maxX) {
        nextX = this.maxX;
        vel.x = -sweepSpeed;
      } else if (nextX <= this.minX) {
        nextX = this.minX;
        vel.x = sweepSpeed;
      }
      target.x = nextX;
      target.y = ARENA_CONFIG.VERTICAL.WEAVER_CEILING_Y;
      target.active = true;
    } else {
      target.x = trans.x + vel.x * dt;
      target.y = trans.y + vel.y * dt;
      target.active = true;
    }

    const wallLimit = ARENA_CONFIG.HORIZONTAL.WEAVER_LIMIT_X;
    if (target.x > wallLimit) {
      target.x = wallLimit;
      if (vel.x > 0) vel.x = 0;
    } else if (target.x < -wallLimit) {
      target.x = -wallLimit;
      if (vel.x < 0) vel.x = 0;
    }

    const ceilingLimit = ARENA_CONFIG.VERTICAL.CEILING_Y;
    const floorLimit = ARENA_CONFIG.VERTICAL.FLOOR_Y;
    if (target.y > ceilingLimit) {
      target.y = ceilingLimit;
      if (vel.y > 0) vel.y = 0;
      trav.isGrounded = false;
      trav.isWallClinging = false;
    } else if (target.y < floorLimit) {
      target.y = floorLimit;
      if (vel.y < 0) vel.y = 0;
      trav.isGrounded = true;
      trav.isWallClinging = false;
    } else {
      trav.isGrounded = false;
      const wallThreshold = ARENA_CONFIG.HORIZONTAL.WALL_CLING_THRESHOLD_X;
      if (Math.abs(target.x) >= wallThreshold) {
        trav.isWallClinging = true;
        trav.wallNormalX = target.x > 0 ? -1 : 1;
      } else {
        trav.isWallClinging = false;
        trav.wallNormalX = 0;
      }
    }

    if (trans) {
      if (
        trans.scaleX === undefined ||
        trans.scaleY === undefined ||
        trans.scaleZ === undefined ||
        trans.prevScaleX === undefined ||
        trans.prevScaleY === undefined ||
        trans.prevScaleZ === undefined
      ) {
        trans.scaleX = 1.0;
        trans.scaleY = 1.0;
        trans.scaleZ = 1.0;
        trans.prevScaleX = 1.0;
        trans.prevScaleY = 1.0;
        trans.prevScaleZ = 1.0;
      }
      trans.prevScaleX = trans.scaleX;
      trans.prevScaleY = trans.scaleY;
      trans.prevScaleZ = trans.scaleZ;

      let targetScaleX = 1.0;
      let targetScaleY = 1.0;
      let targetScaleZ = 1.0;

      const targetQuat = new BABYLON.Quaternion();

      if (ai) {
        if (ai.state === "SWEEPING") {
          const pulse =
            Math.sin(ai.timeInState * WEAVER_AI_TUNING.ANIMATION.PULSE_FREQ) *
            WEAVER_AI_TUNING.ANIMATION.PULSE_BASE;
          targetScaleX = 1.0 + pulse;
          targetScaleY = 1.0 - pulse;

          const rollAngle = -vel.x * WEAVER_AI_TUNING.ANIMATION.ROLL_ANGLE_SCALE;
          const yawAngle =
            Math.sin(ai.timeInState * WEAVER_AI_TUNING.ANIMATION.YAW_PITCH_ROLL_FREQ) *
            WEAVER_AI_TUNING.ANIMATION.YAW_PITCH_ROLL_AMP;
          BABYLON.Quaternion.RotationYawPitchRollToRef(yawAngle, 0, rollAngle, targetQuat);
        } else if (ai.state === "DASHING") {
          const speed = Math.sqrt(vel.x * vel.x + vel.y * vel.y);
          if (speed < WEAVER_AI_TUNING.DASH.SPEED_THRESHOLD) {
            targetScaleY = WEAVER_AI_TUNING.DASH.SQUASH_STRETCH.PREP_Y;
            targetScaleX = WEAVER_AI_TUNING.DASH.SQUASH_STRETCH.PREP_X;
            targetScaleZ = WEAVER_AI_TUNING.DASH.SQUASH_STRETCH.PREP_Z;
          } else {
            const stretch = Math.min(
              WEAVER_AI_TUNING.DASH.SQUASH_STRETCH.STRETCH_MAX,
              (speed / WEAVER_AI_TUNING.DASH.SQUASH_STRETCH.STRETCH_SPEED_BASIS) *
                WEAVER_AI_TUNING.DASH.SQUASH_STRETCH.STRETCH_MAX
            );
            targetScaleY = 1.0 + stretch;
            targetScaleX = 1.0 - stretch * 0.5;
            targetScaleZ = 1.0 - stretch * 0.5;

            const angle = Math.atan2(vel.y, vel.x) + Math.PI / 2;
            BABYLON.Quaternion.RotationAxisToRef(BABYLON.Axis.Z, angle, targetQuat);
          }
        } else if (ai.state === "RETURNING") {
          targetScaleY = WEAVER_AI_TUNING.RETURN.SQUASH_STRETCH.Y;
          targetScaleX = WEAVER_AI_TUNING.RETURN.SQUASH_STRETCH.X;
          BABYLON.Quaternion.RotationYawPitchRollToRef(0, 0, 0, targetQuat);
        } else if (ai.state === "DEFEATED") {
          targetScaleX = WEAVER_AI_TUNING.DEFEATED.SCALE;
          targetScaleY = WEAVER_AI_TUNING.DEFEATED.SCALE;
          targetScaleZ = WEAVER_AI_TUNING.DEFEATED.SCALE;
          BABYLON.Quaternion.RotationYawPitchRollToRef(0, 0, 0, targetQuat);
        }
      }

      const sx = trans.scaleX ?? 1.0;
      const sy = trans.scaleY ?? 1.0;
      const sz = trans.scaleZ ?? 1.0;

      trans.scaleX = sx + (targetScaleX - sx) * WEAVER_AI_TUNING.ANIMATION.LERP_RATE * dt;
      trans.scaleY = sy + (targetScaleY - sy) * WEAVER_AI_TUNING.ANIMATION.LERP_RATE * dt;
      trans.scaleZ = sz + (targetScaleZ - sz) * WEAVER_AI_TUNING.ANIMATION.LERP_RATE * dt;

      const currentQuat = new BABYLON.Quaternion(trans.qx, trans.qy, trans.qz, trans.qw);
      BABYLON.Quaternion.SlerpToRef(
        currentQuat,
        targetQuat,
        WEAVER_AI_TUNING.ANIMATION.LERP_RATE * dt,
        currentQuat
      );
      trans.qx = currentQuat.x;
      trans.qy = currentQuat.y;
      trans.qz = currentQuat.z;
      trans.qw = currentQuat.w;
    }
  }
}

src/gameplay/weaver/states/WeaverDashing:
import { IWeaverState, WeaverStateType } from "../IWeaverState";
import { GameEvent } from "../../../core/events/GameEvents";
import { WEAVER_AI_TUNING, VISUAL_JUICE_CONFIG } from "../../../core/engine/ArenaConfig";
import { SystemContext } from "../../../core/engine/SystemContext";
import {
  TransformComponent,
  HealthComponent,
  WeaverTraversalComponent,
  WeaverAIComponent
} from "../../../core/ecs/Components";

const HASH = String.fromCharCode(35);

export class WeaverDashingState implements IWeaverState {
  public readonly type: WeaverStateType = "DASHING";
  public readonly name = "WEAVER DASH";
  public readonly hue = HASH + VISUAL_JUICE_CONFIG.WEAVER_COLORS.DASH_PREP;
  private dashCount = 0;
  private maxDashes = 2;
  private currentPhase: "PREP" | "THRUST" | "RECOVER" = "PREP";
  private phaseTimer = 0.0;
  private targetPos = { x: 0, y: 0 };
  private thrustVelocity = { x: 0, y: 0 };

  public enter(ctx: SystemContext): void {
    const healthStore = ctx.stores.get<HealthComponent>("health");
    const health = healthStore.get(ctx.refs.weaver);
    const isBerserk = health
      ? health.current < health.max * WEAVER_AI_TUNING.BERSERK_HP_THRESHOLD
      : false;
    this.dashCount = 0;
    this.maxDashes = isBerserk ? 3 : 2;
    this.startPrep(ctx);
  }

  public exit(): void {}

  private startPrep(ctx: SystemContext): void {
    this.currentPhase = "PREP";
    this.phaseTimer = WEAVER_AI_TUNING.DASH.PREP_TIME;

    const aiComp = ctx.stores.get<WeaverAIComponent>("weaverAI").get(ctx.refs.weaver);
    if (aiComp) {
      aiComp.hue = HASH + VISUAL_JUICE_CONFIG.WEAVER_COLORS.DASH_PREP;
    }

    ctx.commands.dispatch({
      type: "SET_KINEMATIC_VELOCITY",
      entityId: ctx.refs.weaver,
      x: 0,
      y: 0,
      z: 0
    });

    const transforms = ctx.stores.get<TransformComponent>("transform");
    const playerTrans = transforms.get(ctx.refs.player);

    if (playerTrans) {
      this.targetPos.x = playerTrans.x;
      this.targetPos.y = playerTrans.y;
    } else {
      this.targetPos.x = 0;
      this.targetPos.y = 14;
    }
  }

  private startThrust(ctx: SystemContext): void {
    this.currentPhase = "THRUST";
    this.phaseTimer = WEAVER_AI_TUNING.DASH.THRUST_TIME;

    const aiComp = ctx.stores.get<WeaverAIComponent>("weaverAI").get(ctx.refs.weaver);
    if (aiComp) {
      aiComp.hue = HASH + VISUAL_JUICE_CONFIG.WEAVER_COLORS.DASH_THRUST;
    }

    const transforms = ctx.stores.get<TransformComponent>("transform");
    const weaverTrans = transforms.get(ctx.refs.weaver);

    if (weaverTrans) {
      const dx = this.targetPos.x - weaverTrans.x;
      const dy = this.targetPos.y - weaverTrans.y;
      const dist = Math.sqrt(dx * dx + dy * dy) || 1.0;
      const speed =
        this.maxDashes === 3
          ? WEAVER_AI_TUNING.DASH.SPEED_BERSERK
          : WEAVER_AI_TUNING.DASH.SPEED_NORMAL;

      this.thrustVelocity.x = (dx / dist) * speed;
      this.thrustVelocity.y = (dy / dist) * speed;

      ctx.commands.dispatch({
        type: "SET_KINEMATIC_VELOCITY",
        entityId: ctx.refs.weaver,
        x: this.thrustVelocity.x,
        y: this.thrustVelocity.y,
        z: 0
      });
    }
  }

  private startRecover(ctx: SystemContext): void {
    this.currentPhase = "RECOVER";
    this.phaseTimer = WEAVER_AI_TUNING.DASH.RECOVER_TIME;

    const aiComp = ctx.stores.get<WeaverAIComponent>("weaverAI").get(ctx.refs.weaver);
    if (aiComp) {
      aiComp.hue = HASH + VISUAL_JUICE_CONFIG.WEAVER_COLORS.DASH_RECOVER;
    }

    ctx.commands.dispatch({
      type: "SET_KINEMATIC_VELOCITY",
      entityId: ctx.refs.weaver,
      x: 0,
      y: 0,
      z: 0
    });

    ctx.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, { amplitude: 0.8, duration: 0.4 });
  }

  public update(ctx: SystemContext, dt: number): WeaverStateType | null {
    this.phaseTimer -= dt;
    const aiComp = ctx.stores.get<WeaverAIComponent>("weaverAI").get(ctx.refs.weaver);

    if (this.currentPhase === "PREP") {
      const strobeHz = WEAVER_AI_TUNING.DASH.STROBE_FREQ;
      const step = Math.floor(this.phaseTimer * strobeHz);
      if (aiComp) {
        aiComp.hue =
          step % 2 === 0
            ? HASH + VISUAL_JUICE_CONFIG.WEAVER_COLORS.DASH_THRUST
            : HASH + VISUAL_JUICE_CONFIG.WEAVER_COLORS.DASH_PREP;
      }

      if (Math.random() < WEAVER_AI_TUNING.DASH.CAMERA_SHAKE_PREP_FREQ) {
        ctx.broker.publish(GameEvent.CAMERA_SHAKE_TRIGGERED, {
          amplitude: WEAVER_AI_TUNING.DASH.CAMERA_SHAKE_PREP_AMP,
          duration: WEAVER_AI_TUNING.DASH.CAMERA_SHAKE_PREP_DUR
        });
      }

      if (this.phaseTimer <= 0) {
        this.startThrust(ctx);
      }
    } else if (this.currentPhase === "THRUST") {
      const traversalStore = ctx.stores.get<WeaverTraversalComponent>("weaverTraversal");
      const trav = traversalStore.get(ctx.refs.weaver);
      const isGraceOver =
        this.phaseTimer <
        WEAVER_AI_TUNING.DASH.THRUST_TIME - WEAVER_AI_TUNING.DASH.COLLISION_GRACE_TIME;
      const hitWallOrGround = isGraceOver && trav ? trav.isWallClinging || trav.isGrounded : false;

      if (this.phaseTimer <= 0 || hitWallOrGround) {
        this.startRecover(ctx);
      }
    } else if (this.currentPhase === "RECOVER") {
      if (this.phaseTimer <= 0) {
        this.dashCount++;
        if (this.dashCount >= this.maxDashes) {
          return "RETURNING";
        } else {
          this.startPrep(ctx);
        }
      }
    }
    return null;
  }
}

