.overlay-subtitle {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0 0 32px 0;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.overlay-btn {
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  color: var(--text-main);
  padding: 14px 32px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.2em;
